    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            java.util.Map<String, Integer> scores = new java.util.HashMap<>();
            scores.put("Ann", 30);
            scores.put("Bob", 20);
            scores.put("Cid", 30);
            scores.put("Dee", 10);
            check("tied players share rank 1 and rank 3 follows",
                    "[1. Ann (30), 1. Cid (30), 3. Bob (20), 4. Dee (10)]",
                    StandingsRanker.standings(scores).toString());
            check("rankOf a tied leader", 1, StandingsRanker.rankOf(scores, "Cid"));
            check("rankOf after the tie", 3, StandingsRanker.rankOf(scores, "Bob"));
            check("rankOf last place", 4, StandingsRanker.rankOf(scores, "Dee"));
            check("rankOf an unknown player", -1, StandingsRanker.rankOf(scores, "Eve"));

            java.util.Map<String, Integer> flat = new java.util.HashMap<>();
