import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class StandingsRanker {

    public static List<String> standings(Map<String, Integer> scores) {
        List<String> names = new ArrayList<>(scores.keySet());
        names.sort((left, right) -> {
            int byScore = Integer.compare(scores.get(right), scores.get(left));
            if (byScore != 0) {
                return byScore;
            }
            return left.compareTo(right);
        });

        List<String> lines = new ArrayList<>();
        int rank = 0;
        int previousScore = 0;
        for (int i = 0; i < names.size(); i++) {
            String name = names.get(i);
            int score = scores.get(name);
            if (i == 0 || score != previousScore) {
                rank = i + 1;
                previousScore = score;
            }
            lines.add(rank + ". " + name + " (" + score + ")");
        }
        return lines;
    }

    public static int rankOf(Map<String, Integer> scores, String name) {
        if (!scores.containsKey(name)) {
            return -1;
        }
        int mine = scores.get(name);
        int better = 0;
        for (int other : scores.values()) {
            if (other > mine) {
                better++;
            }
        }
        return better + 1;
    }
}
